import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Marek Zajac"
__copyright__ = "Copyright (C) 2021, Nokia"
__email__ = "marek.zajac@nokia.com"


class ScenarioUeStop(GenericRtg):
    """ScenarioUeStop command class."""

    def __init__(self, connection, ids=None, detach=False, parameters=None, prompt=None, newline_chars=None, runner=None):
        """
        Scenario ue stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ids: list of session IDs
        :param detach: optional detach flag
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ScenarioUeStop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ids = ids
        self.detach = detach
        self.current_ret = {}
        self.parameters = parameters

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "scenario ue stop"

        if self.ids:
            for id_ in self.ids:
                cmd += f" {id_}"

        if self.detach:
            cmd += " detach"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_sucessfully_stopped(line)
                self._parse_warnings(line)
            except ParsingDone:
                pass
        return super(ScenarioUeStop, self).on_new_line(line, is_full_line)

    # Example line: Stopping UE sessions: 1-attach(X), 2-attach(X)
    _re_successfuly_stopped = re.compile(r"Stopping UE sessions: (((\d+)-(.*)),?)+")

    def _parse_sucessfully_stopped(self, line):
        """
        Scenario ue stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if "Stopping UE sessions:" in line:
            session_ids = [x.strip().replace("(X)", "").split("-")[0] for x in line.replace("Stopping UE sessions: ", "").split(",")]
            self.current_ret["SESSION_IDS"] = session_ids
            raise ParsingDone

    def _parse_warnings(self, line):
        """
        Scenario ue stop command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if "WARNING" in line:
            if "WARNINGS" not in self.current_ret:
                self.current_ret["WARNINGS"] = []
            self.current_ret["WARNINGS"].append(line)
            raise ParsingDone


